import json
PAIRS = [["function askNick(after){", "/* ================= chiptune (nick screen and pause) =================\n   Original 8-bit march, square lead + triangle bass + noise hat, WebAudio only. */\nconst CHIP=(()=>{let on=false,timer=null,next=0,step=0,bus=null;\n  const N=n=>n?440*Math.pow(2,(n-69)/12):0;\n  const LEAD=[72,0,72,75,77,0,75,72, 70,0,70,72,74,0,70,67, 72,0,72,75,79,0,77,75, 74,72,70,74,72,0,0,0,\n              67,0,67,70,72,0,70,67, 65,0,65,67,70,0,67,63, 67,0,70,72,75,0,74,72, 70,72,74,70,72,0,0,0];\n  const BASS=[48,48,55,55,53,53,55,55, 46,46,53,53,50,50,55,55, 48,48,55,55,51,51,53,53, 50,50,55,55,48,48,43,43,\n              43,43,50,50,48,48,50,50, 41,41,48,48,46,46,43,43, 43,43,48,48,51,51,50,50, 46,46,50,50,48,48,43,43];\n  const SP=60/152/2;\n  function note(type,f,t,d,v){if(!f)return;const o=AC.createOscillator(),g=AC.createGain();o.type=type;o.frequency.setValueAtTime(f,t);g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(0.0001,t+d);o.connect(g);g.connect(bus);o.start(t);o.stop(t+d+0.02)}\n  function hat(t,v){const len=Math.floor(0.035*AC.sampleRate),b=AC.createBuffer(1,len,AC.sampleRate),d=b.getChannelData(0);for(let i=0;i<len;i++)d[i]=Math.random()*2-1;const s=AC.createBufferSource(),g=AC.createGain();s.buffer=b;g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(0.0001,t+.035);s.connect(g);g.connect(bus);s.start(t)}\n  function tick(){if(!on||!AC)return;while(next<AC.currentTime+0.15){const i=step%LEAD.length;note('square',N(LEAD[i]),next,SP*.85,.06);note('triangle',N(BASS[i]),next,SP*.95,.14);hat(next,i%2?.035:.015);next+=SP;step++}}\n  return{get on(){return on},start(){if(on||!SV.snd)return;ac();if(!AC)return;bus=AC.createGain();bus.gain.value=.9;bus.connect(AC.destination);on=true;step=0;next=AC.currentTime+0.06;timer=setInterval(tick,40);tick()},\n    stop(){if(!on)return;on=false;clearInterval(timer);try{bus.gain.setTargetAtTime(0,AC.currentTime,.05);const b=bus;setTimeout(()=>{try{b.disconnect()}catch(e){}},400)}catch(e){}}};\n})();\nfunction chipSync(){const want=!$('#ovNick').hidden||!$('#ovPause').hidden;if(want&&SV.snd)CHIP.start();else CHIP.stop()}\nnew MutationObserver(chipSync).observe($('#ovNick'),{attributes:true,attributeFilter:['hidden']});\nnew MutationObserver(chipSync).observe($('#ovPause'),{attributes:true,attributeFilter:['hidden']});\n['pointerdown','keydown','focusin'].forEach(e=>$('#ovNick').addEventListener(e,()=>{if(!$('#ovNick').hidden&&SV.snd)CHIP.start()}));\ndocument.addEventListener('visibilitychange',()=>{if(document.hidden)CHIP.stop();else chipSync()});\n\nfunction askNick(after){", 1], ["$('#pSnd').onclick=()=>{SV.snd=!SV.snd;save();$('#pSnd').textContent='Звук: '+(SV.snd?'вкл':'выкл')};", "$('#pSnd').onclick=()=>{SV.snd=!SV.snd;save();$('#pSnd').textContent='Звук: '+(SV.snd?'вкл':'выкл');chipSync()};", 1]]
s = open('index.html', encoding='utf-8').read()
for old, new, cnt in PAIRS:
    assert s.count(old) == cnt, old[:80]
    s = s.replace(old, new)
open('index.html', 'w', encoding='utf-8').write(s)
print('v6 applied')
